export const wordDescriptions: Record<string, WordDescription> = Object.fromEntries(
  Object.entries(encryptedWordDescriptions).map(([word, description]) => [
    decrypt(word),
    {
      en: decrypt(description.en),
      it: decrypt(description.it),
      fr: decrypt(description.fr),
      de: decrypt(description.de),
      es: decrypt(description.es),
      hu: decrypt(description.hu),
      sv: decrypt(description.sv),
    },
  ]),
);

function decrypt(value: string): string {
  return value.replace(/[a-z]/gi, (letter) => shiftLetter(letter, -caesarShift));
}

function shiftLetter(letter: string, shift: number): string {
  const alphabetStart = letter >= "a" && letter <= "z" ? 97 : 65;
  const alphabetSize = 26;
  const charOffset = letter.charCodeAt(0) - alphabetStart;
  const shiftedOffset = (charOffset + shift + alphabetSize) % alphabetSize;

  return String.fromCharCode(alphabetStart + shiftedOffset);
}

export function getWordDescription(word: string | undefined): WordDescription | null {
  if (!word) {
    return null;
  }

  return wordDescriptions[word.trim().toLowerCase()] ?? null;
}
